// Expo-only machinery for the native entrypoint. Kept out of lib/pkce.ts so the expo-crypto /
// expo-secure-store imports never reach the web, desktop, or server bundles.
import * as Crypto from "expo-crypto";
import * as SecureStore from "expo-secure-store";
import { TOKEN_KEY, type TokenStore } from "./browser-storage";
import { Pkce } from "./pkce";

// Reads go through an in-memory cache: SecureStore.getItem is a synchronous native hop (Keychain /
// Keystore) and the bearer plugin asks for the token on every request. All mutations flow through
// this store, so the cache can't go stale. SecureStore has no synchronous delete; an empty value
// reads back as signed-out ("").
export class SecureTokenStore implements TokenStore {
  #cached: string | undefined;

  getToken() {
    return (this.#cached ??= SecureStore.getItem(TOKEN_KEY) ?? "");
  }
  setToken(token: string) {
    this.#cached = token;
    SecureStore.setItem(TOKEN_KEY, token);
  }
  clearToken() {
    this.#cached = "";
    SecureStore.setItem(TOKEN_KEY, "");
  }
}

// Hermes has no crypto.subtle — expo-crypto digests the PKCE verifier instead.
export const expoChallengeS256 = async (verifier: string) =>
  Pkce.fromBase64(
    await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, verifier, {
      encoding: Crypto.CryptoEncoding.BASE64,
    }),
  );
